public int findLargestSubstring(List<String> strings) {
        Set<String> allSubstrings = new HashSet<>();
        Set<String> allInversedSubstrings = new HashSet<>();

        for (String s : strings) {
            int n = s.length();
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j <= n; j++) {
                    String sub = s.substring(i, j);
                    allSubstrings.add(sub);
                    allInversedSubstrings.add(new StringBuilder(sub).reverse().toString());
                }
            }
        }

        // Check for each substring if it or its inverse exists in another string
        int maxLen = 0;
        for (String s : strings) {
            int n = s.length();
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j <= n; j++) {
                    String sub = s.substring(i, j);
                    String invSub = new StringBuilder(sub).reverse().toString();
                    // Check if sub or invSub appears in any OTHER string
                    boolean found = false;
                    for (String other : strings) {
                        if (other == s) continue;
                        if (other.contains(sub) || other.contains(invSub)) {
                            found = true;
                            break;
                        }
                    }
                    if (found) {
                        maxLen = Math.max(maxLen, sub.length());
                    }
                }
            }
        }

        return maxLen;
    }

