    int count = 0;
    int n = numbers.length;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j && numbers[i] == 2 * numbers[j]) {
                count++;
                break; // Only count each element once
            }
        }
    }
    return count;
}

