public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Build adjacency list for the graph
    // Each node is represented by a pair of coordinates (x, y). Since n <= 10^5 possibly,
    // but coordinates are within n x n, we can map (x, y) to a single integer: x * n + y (if 0-indexed)
    // Or we can use a map from coordinate pair to list of neighbors.

    // Let's use a map: key = x * n + y (assuming 0 <= x, y < n)
    java.util.Map<Long, java.util.List<Long>> graph = new java.util.HashMap<>();

    for (int[] path : paths) {
        if (path.length < 4) continue;
        int x1 = path[0], y1 = path[1], x2 = path[2], y2 = path[3];
        long node1 = (long) x1 * n + y1;
        long node2 = (long) x2 * n + y2;

        // Validate coordinates are within bounds
        if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
            continue;
        }

        // Add edges for undirected graph
        graph.computeIfAbsent(node1, k -> new java.util.ArrayList<>()).add(node2);
        graph.computeIfAbsent(node2, k -> new java.util.ArrayList<>()).add(node1);
    }

    // Get start and end nodes
    long startNode = (long) start[0] * n + start[1];
    long endNode = (long) end[0] * n + end[1];

    // BFS to check if there's a path from startNode to endNode
    if (startNode == endNode) {
        return "can be travelled";
    }

    java.util.Set<Long> visited = new java.util.HashSet<>();
    java.util.Queue<Long> queue = new java.util.LinkedList<>();

    visited.add(startNode);
    queue.add(startNode);

    while (!queue.isEmpty()) {
        long currentNode = queue.poll();

        if (currentNode == endNode) {
            return "can be travelled";
        }

        if (graph.containsKey(currentNode)) {
            for (long neighbor : graph.get(currentNode)) {
                if (!visited.contains(neighbor)) {
                    visited.add(neighbor);
                    queue.add(neighbor);
                }
            }
        }
    }

    return "cannot be travelled";
}

