public static String appx(String word1, String word2) {
    // Convert words to uppercase and sort their characters
    char[] chars1 = word1.toUpperCase().toCharArray();
    char[] chars2 = word2.toUpperCase().toCharArray();
    java.util.Arrays.sort(chars1);
    java.util.Arrays.sort(chars2);

    // Count common characters
    int commonCount = 0;
    int i = 0, j = 0;
    while (i < chars1.length && j < chars2.length) {
        if (chars1[i] == chars2[j]) {
            commonCount++;
            i++;
            j++;
        } else if (chars1[i] < chars2[j]) {
            i++;
        } else {
            j++;
        }
    }

    // Calculate denominator as sum of lengths
    int denominator = word1.length() + word2.length();

    // If no common characters, return "0"
    if (commonCount == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    // Reduce the fraction
    int numerator = commonCount;
    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;

    // If denominator is 1, return just the numerator
    if (denominator == 1) {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator;
    }

    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

