public static String convertDatesToWeekdays(String date) {
    java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("MM dd yyyy");
    java.text.SimpleDateFormat daySdf = new java.text.SimpleDateFormat("EEEE");
    java.text.SimpleDateFormat fullSdf = new java.text.SimpleDateFormat("MMMM d, yyyy");
