        if (rem < 0) rem += k;
        freq[rem]++;
    }
    if (freq[0] % 2 != 0) {
        return false;
    }
    for (int i = 1; i <= k / 2; i++) {
        int j = k - i;
        if (freq[i] != freq[j]) {
            return false;
        }
    }
    return true;
}

