public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }

    int[] remainderCount = new int[k];

    for (int num : arr) {
        int remainder = num % k;
        if (remainder < 0) {
            remainder += k;
        }
        remainderCount[remainder]++;
    }

    // The count of elements with remainder 0 must be even
    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    // For every remainder r (1 <= r <= k-1), the count of elements with remainder r
    // must equal the count of elements with remainder (k - r)
    for (int r = 1; r < (k + 1) / 2; r++) {
        if (remainderCount[r] != remainderCount[k - r]) {
            return false;
        }
    }

    // If k is odd, we also need to check the middle remainder (k/2)
    if (k % 2 != 0) {
        if (remainderCount[k / 2] % 2 != 0) {
            return false;
        }
    }

    return true;
}

