        graph.get(u).add(v);
        graph.get(v).add(u);
    }

    // DFS to calculate minimum time
    // We'll use a helper method that returns the number of edges that need to be traversed
    // This is effectively the number of nodes visited * 2, but we can think in terms of edges.
    // If a subtree has no apples, we don't go down that path.
    // If a subtree has apples, we must go down and up, adding 2 edges to the parent.

    // Let's use a stack-based or recursive DFS. Recursive is cleaner for tree problems usually.
    // We need to avoid going back to the parent.

    // Re-initializing for standard DFS approach
    int[] result = {0};

