    private int dfs(int node, int parent, List<List<Integer>> graph, boolean[] hasApple) {
        int totalChildrenTime = 0;
        for (int neighbor : graph.get(node)) {
            if (neighbor == parent) continue;

            int childTime = dfs(neighbor, node, graph, hasApple);

            // If the child subtree has any apples (indicated by childTime > 0) 
