public String sortString(String s) {
        int[] freq = new int[26];
        for (char c : s.toCharArray()) {
            freq[c - 'a']++;
        }

        StringBuilder result = new StringBuilder();
        int n = s.length();

        while (result.length() < n) {
            boolean picked = false;

            // Step 1-3: Pick characters in ascending order
            for (char c = 'a'; c <= 'z'; c++) {
                if (freq[c - 'a'] > 0) {
                    result.append(c);
                    freq[c - 'a']--;
                    picked = true;
                }
            }

            // Step 4-6: Pick characters in descending order
            for (char c = 'z'; c >= 'a'; c--) {
                if (freq[c - 'a'] > 0) {
                    result.append(c);
                    freq[c - 'a']--;
                    picked = true;
                }
            }

            if (!picked) {
                break;
            }
        }

        return result.toString();
    }

