public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) {
        return false;
    }

    int totalRequired = (1 << k);
    boolean[] seen = new boolean[totalRequired];
    int count = 0;

    // First window
    int first = 0;
    for (int i = 0; i < k; i++) {
        first = (first << 1) | (s.charAt(i) - '0');
    }
    if (!seen[first]) {
        seen[first] = true;
        count++;
    }

    // Slide the window
    for (int i = k; i < s.length(); i++) {
        // Remove the leftmost bit, shift left, add new bit
        int value = first;
        value = (value << 1) | (s.charAt(i) - '0');
        // Mask to keep only last k bits
        value = value & (totalRequired - 1);

        if (!seen[value]) {
            seen[value] = true;
            count++;
            if (count == totalRequired) {
                return true;
            }
        }
        first = value;
    }

    return count == totalRequired;
}

