public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (n < k) {
        return false;
    }

    // If there are not enough distinct substrings of length k possible, return false
    // Total possible binary strings of length k is 2^k
    // We need at least k distinct substrings to possibly cover all, but more importantly,
    // the number of distinct substrings we can have is at most n - k + 1
    // If n - k + 1 < 2^k, then it's impossible to have all 2^k substrings
    if ((1 << k) > n - k + 1) {
        return false;
    }

    Set<String> seen = new HashSet<>();
    for (int i = 0; i <= n - k; i++) {
        String substring = s.substring(i, i + k);
        seen.add(substring);
    }

    return seen.size() == (1 << k);
}

