public int minOperations(int n) {
    // The sum of array arr where arr[i] = 2*i + 1 is n*n
    // The target value for each element to make all equal is n (since sum = n*n, average = n)
    // We need to find the minimum number of operations to make all elements equal to n
    // arr[i] = 2*i + 1
    // For each i, if arr[i] > n, we need to move (arr[i] - n) elements out
    // if arr[i] < n, we need to bring (n - arr[i]) elements in
    // The total operations is the sum of (arr[i] - n) for all i where arr[i] > n
    // which is the same as sum of (n - arr[i]) for all i where arr[i] < n

    // Let's think about it differently:
    // arr = [1, 3, 5, 7, ..., 2n-1]
    // target = n
    // For i from 0 to n-1:
    //   arr[i] = 2*i + 1
    //   diff = arr[i] - n = 2*i + 1 - n
    //   If diff > 0, we need to move diff out
    // The total operations = sum of max(0, 2*i + 1 - n) for i = 0 to n-1

