public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    int a = 1, b = 1;
    int[] fibs = {1, 1};
    while (true) {
        if (a + b > k) {
            if (b <= k) {
                fibs = java.util.Arrays.copyOf(fibs, fibs.length + 1);
                fibs[fibs.length - 1] = b;
            }
            break;
        }
        int next = a + b;
        a = b;
        b = next;
        fibs = java.util.Arrays.copyOf(fibs, fibs.length + 1);
        fibs[fibs.length - 1] = next;
    }

    // Use greedy approach: always subtract the largest Fibonacci number <= k
    int count = 0;
    for (int i = fibs.length - 1; i >= 0 && k > 0; i--) {
        if (fibs[i] <= k) {
            k -= fibs[i];
            count++;
        }
    }

    return count;
}

