    if (s == null || s.isEmpty()) {
        return s;
    }

    char[] stack = new char[s.length()];
    int top = -1;

    for (char c : s.toCharArray()) {
        // Check if the current character and the top of the stack are adjacent and form a pair
        if (top >= 0) {
            char prev = stack[top];
            // Check if one is lowercase and the other is uppercase of the same letter
            if ((Character.isLowerCase(c) && Character.toUpperCase(c) == prev) ||
                (Character.isUpperCase(c) && Character.toLowerCase(c) == prev)) {
                // Pop the stack (remove the pair)
                top--;
                continue;
            }
        }
        // Push the current character onto the stack
        top++;
        stack[top] = c;
    }

    // Build the result string from the stack
    StringBuilder result = new StringBuilder();
    for (int i = 0; i <= top; i++) {
        result.append(stack[i]);
    }

    return result.toString();
}

