public String getSmallestString(int n, int k) {
    char[] res = new char[n];
    // Initialize all characters to 'a', which contributes 1 to the value
    for (int i = 0; i < n; i++) {
        res[i] = 'a';
    }
    // We need to add (k - n) more to the value by increasing characters from the right (to keep lexicographically smallest)
    int remaining = k - n;
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int maxAdd = 25; // 'z' - 'a' = 25
        int toAdd = Math.min(remaining, maxAdd);
        res[i] = (char) ('a' + toAdd);
        remaining -= toAdd;
    }
    return new String(res);
}

