public static boolean isBoomerang(int[][] points) {
    // If there are not exactly 3 points, it's not a valid boomerang
    if (points == null || points.length != 3) {
        return false;
    }

    // Calculate the cross product to determine if all three points are collinear
    // Cross product of (B - A) and (C - A)
    int dx1 = points[1][0] - points[0][0];
    int dy1 = points[1][1] - points[0][1];
    int dx2 = points[2][0] - points[0][0];
    int dy2 = points[2][1] - points[0][1];

    // Cross product
    int cross = dx1 * dy2 - dy1 * dx2;

    // If cross product is zero, points are collinear (not a boomerang)
    // Also check for duplicate points - if any two points are the same, it's not a valid boomerang
    if (cross == 0) {
        return false;
    }

    // Check for duplicate points
    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                return false;
            }
        }
    }

    return true;
}

