public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    // Initialize DP array
    int[] dp = new int[n + 1];
    java.util.Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    // Fill the DP table
    for (int i = 1; i <= n; i++) {
        // Try all perfect squares less than or equal to i
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] != Integer.MAX_VALUE) {
                dp[i] = Math.min(dp[i], dp[i - square] + 1);
            }
        }
    }

    return dp[n];
}

