public static int minPerfectSquareSum(int n) {
    // dp[i] represents the minimum number of perfect squares that sum to i
    int[] dp = new int[n + 1];
    // Initialize dp[0] = 0, and all others to infinity (we can use n+1 as a safe upper bound)
    java.util.Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    // Precompute perfect squares up to n
    // Find all perfect squares <= n
    java.util.List<Integer> squares = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        squares.add(i * i);
