    for (int i = 1; i <= n; i++) {
        for (int sq : squares) {
            if (sq > i) {
                break;
            }
            if (dp[i - sq] + 1 < dp[i]) {
                dp[i] = dp[i - sq] + 1;
            }
        }
    }

    return dp[n];
}

